<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ArrowLeft, ArrowRight, BriefcaseBusiness, Check, CircleHelp, Lightbulb, Paperclip } from 'lucide-vue-next'
import { api, type AuthResponse } from '../services/api'
const emit = defineEmits<{ complete: [auth: AuthResponse] }>()
const step = ref(1); const busy = ref(false); const error = ref('')
const sectors = ref(['Ventas', 'Repartidores', 'Administracion', 'Choferes', 'Contabilidad', 'Recepcionista', 'Mecanica', 'Logistica', 'Construccion', 'Informatica'])
const chosen = ref<string[]>([])
const form = ref({ fullName: '', identityCard: '', phone: '', email: '', password: '', residenceArea: 'San Jose de Mayo (Centro)', profileName: '', availability: 'FULL_TIME', hasVehicle: false, latestJob: '', experienceDescription: '' })
onMounted(async () => { try { sectors.value = await api.getSectors() } catch { } })
function toggle(sector: string) { chosen.value = chosen.value.includes(sector) ? chosen.value.filter((item) => item !== sector) : [...chosen.value, sector] }
function next() { error.value = ''; if (step.value === 1 && (!form.value.fullName || !form.value.identityCard || !form.value.phone || !form.value.email || form.value.password.length < 12)) { error.value = 'Completa los campos obligatorios. La contrasena debe tener al menos 12 caracteres.'; return }; if (step.value === 2 && (!form.value.profileName || !chosen.value.length)) { error.value = 'Indica un perfil y al menos un rubro.'; return }; step.value++ }
async function complete() { busy.value = true; error.value = ''; try { emit('complete', await api.registerApplicant({ ...form.value, sectors: chosen.value })) } catch (exception) { error.value = exception instanceof Error ? exception.message : 'No fue posible completar el registro.' } finally { busy.value = false } }
</script>
<template>
  <main class="registration"><header class="registration__header"><div class="registration__brand"><span class="registration__mark"><CircleHelp :size="18" /></span><b>CENTRO COMERCIAL<br>E INDUSTRIAL<br>DE SAN JOSE</b></div><span class="registration__divider"></span><h1>Registro de Postulante</h1><ol class="stepper"><li v-for="index in 3" :key="index" :class="{ 'stepper__step--active': step === index, 'stepper__step--done': step > index }"><b>{{ step > index ? 'OK' : index }}</b>{{ ['Datos Personales', 'Primer Perfil', 'CV / Experiencia'][index - 1] }}</li></ol></header><section class="registration-card"><template v-if="step === 1"><h2>Datos Personales</h2><p>Completa la informacion basica para dar de alta tu ficha de postulante.</p><div class="form-grid"><label class="form-field form-field--wide">Nombre completo <i>*</i><input v-model="form.fullName" placeholder="Ingresa tu nombre y apellido"></label><label class="form-field">Cedula de Identidad <i>*</i><input v-model="form.identityCard" placeholder="Ej: 4.876.543-2"></label><label class="form-field">Telefono / Celular <i>*</i><input v-model="form.phone" placeholder="Ej: 099 123 456"></label><label class="form-field">Gmail / Correo electronico <i>*</i><input v-model="form.email" type="email" placeholder="usuario@gmail.com"></label><label class="form-field">Escribi una contrasena <i>*</i><input v-model="form.password" type="password" placeholder="Minimo 12 caracteres"></label><label class="form-field form-field--wide">Zona de residencia <i>*</i><select v-model="form.residenceArea"><option>San Jose de Mayo (Centro)</option><option>Ciudad del Plata</option><option>Libertad</option><option>Otra localidad</option></select></label></div></template><template v-else-if="step === 2"><div class="registration-card__notice"><Lightbulb :size="17" /><div><b>Podes tener varios perfiles laborales</b><br>Despues podras crear perfiles adicionales para distintos rubros.</div></div><h2>Primer Perfil Laboral</h2><p>Configura las bases de tu primera postulacion activa.</p><label class="form-field">Nombre de este perfil <i>*</i><input v-model="form.profileName" placeholder="Ej: Perfil Administracion"></label><fieldset class="sector-picker"><legend>Rubros de interes</legend><button v-for="sector in sectors" :key="sector" type="button" class="sector-picker__chip" :class="{ 'sector-picker__chip--selected': chosen.includes(sector) }" @click="toggle(sector)"><Check v-if="chosen.includes(sector)" :size="13" />{{ sector }}</button></fieldset><fieldset class="availability"><legend>Disponibilidad horaria</legend><button type="button" :class="{ 'availability__choice--selected': form.availability === 'FULL_TIME' }" @click="form.availability = 'FULL_TIME'"><b>Full-time</b><small>Mas de 30 horas semanales</small></button><button type="button" :class="{ 'availability__choice--selected': form.availability === 'PART_TIME' }" @click="form.availability = 'PART_TIME'"><b>Part-time</b><small>Menos de 30 horas semanales</small></button></fieldset><label class="registration-card__check"><input v-model="form.hasVehicle" type="checkbox"> Tengo vehiculo propio habilitado</label></template><template v-else><h2>Curriculum Vitae</h2><p>Completa tu experiencia laboral. La carga de archivos estara disponible con S3.</p><div class="upload-placeholder"><Paperclip :size="22" /><div><b>Adjuntar archivo de CV</b><small>PDF o Word, tamaño maximo de 5MB</small></div><button type="button" disabled>Proximamente</button></div><div class="experience-form"><h3><BriefcaseBusiness :size="18" /> Completar experiencia manualmente</h3><label class="form-field">Ultimo empleo / empresa actual<input v-model="form.latestJob" placeholder="Ej: Auxiliar administrativo"></label><label class="form-field">Descripcion de la experiencia<textarea v-model="form.experienceDescription" placeholder="Detalla tareas y logros clave..."></textarea></label></div></template><p v-if="error" class="form-error">{{ error }}</p><footer class="registration-card__actions"><button v-if="step > 1" type="button" class="button button--secondary" @click="step--"><ArrowLeft :size="14" /> Anterior</button><span v-else></span><button v-if="step < 3" type="button" class="button button--primary" @click="next">Continuar <ArrowRight :size="15" /></button><button v-else type="button" class="button button--primary" :disabled="busy" @click="complete">{{ busy ? 'Registrando...' : 'Completar Registro' }} <Check :size="15" /></button></footer></section></main>
</template>